_pool_mod.ThreadPool = ThreadPool
_pool_mod.AsyncResult = AsyncResult
_mod.pool = _pool_mod
_mod.TimeoutError = TimeoutError
sys.modules["multiprocessing"] = _mod
sys.modules["multiprocessing.pool"] = _pool_mod
